export const apUSHistoryFRQs: USHistoryFRQ[] = [...longFRQs, ...shortFRQs, ...dbqFRQs]

export function getApUSHistoryFRQs(): USHistoryFRQ[] {
  return apUSHistoryFRQs
}

export function getLongFRQs(): USHistoryFRQ[] {
  return longFRQs
}

export function getShortFRQs(): USHistoryFRQ[] {
  return shortFRQs
}

export function getDBQs(): USHistoryFRQ[] {
  return dbqFRQs
}

export function generateFullExamFRQs(pool: USHistoryFRQ[] = apUSHistoryFRQs): {
  long: USHistoryFRQ[]
  short: USHistoryFRQ[]
  totalPoints: number
  totalTime: string
} {
  const shuffle = <T>(arr: T[]): T[] => {
    const copy = [...arr]
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[copy[i], copy[j]] = [copy[j], copy[i]]
    }
    return copy
  }

  const selectedLong = shuffle(pool.filter((f) => f.type === 'long')).slice(0, 2)
  const selectedShort = shuffle(pool.filter((f) => f.type === 'short')).slice(0, 2)
  const totalPoints = [...selectedLong, ...selectedShort].reduce((s, f) => s + f.totalPoints, 0)

  return {
    long: selectedLong,
    short: selectedShort,
    totalPoints,
    totalTime: '100 min',
  }
}
